#!/usr/bin/env python3
"""Fake_img_dector v2 upgrade installer.
Run from the ROOT of your repo:   python apply_upgrade.py
Originals are backed up to .upgrade_backup/ first.
"""
import base64, os, shutil, sys

if not (os.path.isdir("backend") and os.path.isdir("frontend")):
    sys.exit("Run this from the repo root (the folder containing backend/ and frontend/).")

FILES = {
 "README.md": "",
 ".gitignore": "",
 "backend/app/main.py": "",
 "backend/app/routers/analyze.py": "",
 "backend/app/schemas/schema.py": "",
 "backend/app/services/image_service.py": "",
 "backend/app/services/prediction_service.py": "",
 "backend/app/scraper/scraper.py": "",
 "backend/app/utils/helper.py": "",
 "frontend/src/services/api.js": "",
 "frontend/src/pages/Home.jsx": "",
 "frontend/src/components/ResultCard.jsx": "",
 "frontend/src/components/SummaryStats.jsx": "",
 "frontend/src/components/UploadBox.jsx": ""
}

for path, b64 in FILES.items():
    if os.path.exists(path):
        backup = os.path.join(".upgrade_backup", path)
        os.makedirs(os.path.dirname(backup), exist_ok=True)
        shutil.copy2(path, backup)
    os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
    with open(path, "wb") as fh:
        fh.write(base64.b64decode(b64))
    print("updated", path)

print("\nDone. %d files written. Originals saved in .upgrade_backup/" % len(FILES))
